import sys

MOD = 998244353

def solve():
    N = int(sys.stdin.readline())

    cnt = [0] * 7
    total = [0] * 7

    start = 1
    for length in range(1, 7):
        end = min(N, 10 * start - 1)
        if start > N:
            break
        c = end - start + 1
        cnt[length] = c
        total[length] = (start + end) * c // 2 % MOD
        start *= 10

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    polys = []
    for length in range(1, 7):
        c = cnt[length]
        if c == 0:
            continue

        a = pow(10, length, MOD)
        poly = [0] * (c + 1)
        apow = 1
        for k in range(c + 1):
            comb = fact[c] * invfact[k] % MOD * invfact[c - k] % MOD
            poly[k] = comb * apow % MOD
            apow = apow * a % MOD
        polys.append(poly)

    BASE_BYTES = 10

    def multiply(A, B):
        size = len(A) + len(B) - 1
        x = int.from_bytes(b"".join(v.to_bytes(BASE_BYTES, "little") for v in A), "little")
        y = int.from_bytes(b"".join(v.to_bytes(BASE_BYTES, "little") for v in B), "little")
        z = x * y
        raw = z.to_bytes(size * BASE_BYTES, "little")
        return [
            int.from_bytes(raw[i * BASE_BYTES:(i + 1) * BASE_BYTES], "little") % MOD
            for i in range(size)
        ]

    polys.sort(key=len)
    e = polys[0]
    for poly in polys[1:]:
        e = multiply(e, poly)

    g = [0] * N
    for length in range(1, 7):
        if cnt[length] == 0:
            continue

        a = pow(10, length, MOD)
        s = total[length]
        prev = 0
        for k in range(N):
            without_len = (e[k] - a * prev) % MOD
            g[k] = (g[k] + s * without_len) % MOD
            prev = without_len

    ans = 0
    for k in range(N):
        ans = (ans + fact[k] * fact[N - 1 - k] % MOD * g[k]) % MOD

    print(ans)

